            ExerciseItem(id: UUID(), prompt: "Etichetta su una scatola: «CONSERVARE IN FRIGORIFERO»\n\nChe cosa significa?", options: ["Tenere il prodotto in un luogo caldo", "Tenere il prodotto al fresco, in frigorifero", "Tenere il prodotto al sole", "Mettere il prodotto nel forno"], correctAnswer: "Tenere il prodotto al fresco, in frigorifero", explanation: "L'etichetta indica che il prodotto va tenuto al freddo per non rovinarsi."),
            ExerciseItem(id: UUID(), prompt: "Sulla serranda di un negozio: «CHIUSO PER FERIE»\n\nChe cosa significa?", options: ["Il negozio ha chiuso per sempre", "Il negozio è chiuso perché i titolari sono in vacanza", "Il negozio apre alle 9:00", "Il negozio è in vendita"], correctAnswer: "Il negozio è chiuso perché i titolari sono in vacanza", explanation: "Le ferie sono il periodo di vacanza dal lavoro: il negozio riaprirà più avanti."),
            ExerciseItem(id: UUID(), prompt: "Cartello stradale: «SENSO UNICO»\n\nChe cosa significa?", options: ["Si può andare in una sola direzione", "La strada è chiusa", "Si può andare in due direzioni", "La strada è solo per i pedoni"], correctAnswer: "Si può andare in una sola direzione", explanation: "In una strada a senso unico i veicoli viaggiano in una direzione soltanto."),
            ExerciseItem(id: UUID(), prompt: "Cartello: «DIVIETO DI SOSTA»\n\nChe cosa significa?", options: ["Non ci si può fermare a parcheggiare", "Si può parcheggiare gratis", "Si deve parcheggiare qui", "Si può parcheggiare solo di sera"], correctAnswer: "Non ci si può fermare a parcheggiare", explanation: "«Sosta» è fermarsi con il veicolo: qui non è consentito."),
            ExerciseItem(id: UUID(), prompt: "Cartello: «ZONA PEDONALE»\n\nChe cosa significa?", options: ["Zona riservata alle auto", "Zona per soli pedoni, di norma senza auto", "Zona con molti parcheggi", "Zona dove si va in bicicletta"], correctAnswer: "Zona per soli pedoni, di norma senza auto", explanation: "Una zona pedonale è un'area dove si cammina a piedi, senza il traffico delle auto."),
            ExerciseItem(id: UUID(), prompt: "Cartello in un museo: «NON TOCCARE LE OPERE»\n\nChe cosa significa?", options: ["Si possono toccare le opere", "Le opere si possono toccare solo con i guanti", "Le opere vanno guardate senza toccarle", "Le opere sono in vendita"], correctAnswer: "Le opere vanno guardate senza toccarle", explanation: "Toccare le opere può rovinarle; il cartello chiede di guardare soltanto."),
            ExerciseItem(id: UUID(), prompt: "Sulla porta di un bar: «Orario: 7:00 - 20:30»\n\nChe cosa significa?", options: ["Il bar è aperto solo alla sera", "Il bar apre alle 20:30 e chiude alle 7:00", "Il bar è chiuso dalle 7:00 alle 20:30", "Il bar è aperto dalle 7:00 alle 20:30"], correctAnswer: "Il bar è aperto dalle 7:00 alle 20:30", explanation: "L'orario va letto da sinistra a destra: apertura alle 7:00 e chiusura alle 20:30."),
            ExerciseItem(id: UUID(), prompt: "Cartello in un negozio: «SALDI»\n\nChe cosa significa?", options: ["I prezzi sono ridotti", "I prodotti sono finiti", "Il negozio è chiuso", "Non si accettano carte"], correctAnswer: "I prezzi sono ridotti", explanation: "I saldi sono vendite a prezzo ridotto, con sconti sui prodotti."),
            ExerciseItem(id: UUID(), prompt: "Su un pacco c'è scritto: «FRAGILE»\n\nChe cosa significa?", options: ["Il contenuto è molto pesante", "Il contenuto è da trattare con cura, perché si può rompere", "Il pacco è gratuito", "Il pacco va aperto subito"], correctAnswer: "Il contenuto è da trattare con cura, perché si può rompere", explanation: "«Fragile» indica un contenuto delicato che si rompe facilmente."),
            ExerciseItem(id: UUID(), prompt: "Su un flacone di detersivo: «TENERE FUORI DALLA PORTATA DEI BAMBINI»\n\nChe cosa significa?", options: ["Il prodotto è fatto per i bambini", "Il prodotto va messo dove i bambini non arrivano", "Il prodotto serve a lavare i giochi", "Il prodotto si usa solo con i bambini"], correctAnswer: "Il prodotto va messo dove i bambini non arrivano", explanation: "Il detersivo può far male se maneggiato dai bambini: va custodito in alto o sotto chiave."),
            ExerciseItem(id: UUID(), prompt: "Cartello rosso a forma di ottagono: «STOP»\n\nChe cosa significa?", options: ["Fermarsi e dare la precedenza", "Rallentare soltanto", "Si può passare senza fermarsi", "Parcheggio libero"], correctAnswer: "Fermarsi e dare la precedenza", explanation: "Lo stop obbliga a fermarsi completamente e a dare la precedenza prima di ripartire."),
            ExerciseItem(id: UUID(), prompt: "Cartello: «LAVORI IN CORSO»\n\nChe cosa significa?", options: ["Il lavoro è finito", "Ci sono operai al lavoro: bisogna fare attenzione", "Si cercano operai", "La strada è nuova"], correctAnswer: "Ci sono operai al lavoro: bisogna fare attenzione", explanation: "Il cartello avvisa che sono in corso lavori e che occorre prudenza."),
            ExerciseItem(id: UUID(), prompt: "Cartello su una porta: «VIETATO L'INGRESSO AI NON AUTORIZZATI»\n\nChe cosa significa?", options: ["Entrano tutti", "Possono entrare solo le persone che hanno il permesso", "Si entra pagando", "L'ingresso è gratuito"], correctAnswer: "Possono entrare solo le persone che hanno il permesso", explanation: "Il cartello limita l'ingresso a chi è stato autorizzato."),
            ExerciseItem(id: UUID(), prompt: "Cartello al parco: «INGRESSO 5,00 €»\n\nChe cosa significa?", options: ["Per entrare si pagano 5,00 €", "Si ricevono 5,00 € all'ingresso", "L'ingresso è gratuito", "Il parco chiude alle 5:00"], correctAnswer: "Per entrare si pagano 5,00 €", explanation: "Il prezzo accanto alla parola «ingresso» è quanto si paga per entrare."),
            ExerciseItem(id: UUID(), prompt: "Cartello vicino a un traliccio: «ALTA TENSIONE – PERICOLO DI MORTE»\n\nChe cosa significa?", options: ["Zona di gioco per bambini", "Nelle vicinanze c'è corrente elettrica molto pericolosa", "Zona con molta luce", "Lo spazio è in vendita"], correctAnswer: "Nelle vicinanze c'è corrente elettrica molto pericolosa", explanation: "L'alta tensione può uccidere: il cartello avverte di tenersi a distanza.")
        ]
    )

